  problems as (
    select 'APPLIED_BODY_DRIFT' as kind, pin.signature as detail
    from applied_body_pins pin
    where (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5
    union all
    select 'VOICE_FUNCTION_DRIFT', pin.signature
    from voice_function_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature)
      and md5(replace(prosrc,E'\r\n',E'\n'))=pin.body_md5 and prosecdef=pin.definer and proisstrict=pin.strict_function
      and proconfig=array['search_path=pg_catalog'] and proowner='postgres'::regrole
      and prolang=(select oid from pg_language where lanname=pin.language_name)
      and provolatile::text=pin.volatility and prokind='f' and prorettype=to_regtype(pin.result_type)
      and proacl::text=pin.acl and not proretset and not proleakproof and proparallel='u'
      and probin is null and prosqlbody is null and protrftypes is null and proallargtypes is null and proargmodes is null)
    union all
    select 'TRIGGER_DRIFT', pin.trigger_name
    from trigger_pins pin
    where not exists(select 1 from pg_trigger t where tgrelid=pin.relation::regclass and tgname=pin.trigger_name
