      and tgnargs=0 and octet_length(tgargs)=0 and tgqual is null and (tgconstraint<>0)=pin.deferred
      and tgdeferrable=pin.deferred and tginitdeferred=pin.deferred and tgoldtable is null and tgnewtable is null and tgparentid=0 and tgattr::text='')
    union all
    select 'UPLOAD_TABLE_DRIFT', 'private.agreement_voice_uploads_v1'
    where not exists(select 1 from pg_class where oid=to_regclass('private.agreement_voice_uploads_v1') and relowner='postgres'::regrole and relkind='r' and relpersistence='p'
        and not relispartition and relrowsecurity and relforcerowsecurity and relreplident='d' and reloptions is null and relacl=acldefault('r','postgres'::regrole))
      or exists(select 1 from pg_policies where schemaname='private' and tablename='agreement_voice_uploads_v1')
    union all
    select 'MESSAGE_COLUMN_OR_CONSTRAINT_DRIFT', 'public.agreement_messages'
    where (select count(*) from pg_attribute where attrelid='public.agreement_messages'::regclass and attname='voice_asset_id' and not attisdropped and atttypid='uuid'::regtype and not attnotnull)<>1
      or not exists(select 1 from pg_constraint where conrelid='public.agreement_messages'::regclass and conname='agreement_messages_body_media_check' and convalidated)
      or exists(select 1 from pg_constraint where conrelid='public.agreement_messages'::regclass and conname='agreement_messages_body_photo_check')
    union all
    select 'LINK_GUARD_CONSTRAINT_DRIFT', 'agreement_voice_link_guard_v1'
    where (select count(*) from pg_constraint x where x.conrelid='public.agreement_messages'::regclass and x.conname='agreement_voice_link_guard_v1' and x.contype='t'
        and x.condeferrable and x.condeferred and x.convalidated and x.conparentid=0 and x.conislocal and x.coninhcount=0 and x.contypid=0 and x.conindid=0 and x.confrelid=0
        and exists(select 1 from pg_trigger t where t.tgconstraint=x.oid and t.tgname='agreement_voice_link_guard_v1' and t.tgrelid=x.conrelid))<>1
    union all
    select 'CLOSURE_ACTION_SHAPE_DRIFT', 'private.closure_actions_v5'
    where not exists(select 1 from pg_constraint where conrelid='private.closure_actions_v5'::regclass and conname='closure_action_shape146' and convalidated and pg_get_constraintdef(oid) like '%agreement-voice%')
    union all
    select 'BUCKET_OR_STORAGE_POLICY_DRIFT', 'agreement-voice'
    where not exists(select 1 from storage.buckets where id='agreement-voice' and not public and file_size_limit=4194304 and allowed_mime_types=array['audio/mp4'])
      or not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='agreement_voice_no_client_v1'
        and permissive='RESTRICTIVE' and roles=array['authenticated']::name[] and cmd='ALL' and qual like '%agreement-voice%' and with_check like '%agreement-voice%')
    union all
    select 'RETENTION_CATALOG_DRIFT', 'MEDIA_OBJECTS'
    where not exists(select 1 from private.closure_dataset_catalog_v5 where data_class='MEDIA_OBJECTS' and relations @> array['private.agreement_voice_uploads_v1']::text[])
    union all
    select 'EXPORT_CATALOG_DRIFT', 'private.data_export_dataset_catalog()'
    where jsonb_array_length(private.data_export_dataset_catalog())<>52
      or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) e where e->>'key'='ownAgreementVoice')
    union all
    select 'CERTIFICATE_CARDINALITY', 'closure_source_v5 and closure_erasure_source_v5 must hold exactly one row each'
