    select 'CERTIFICATE_NOT_BOUND', 'the certificate, the live digest, the erasure source row, the readiness and the binding must all agree'
    from cert where certified is null or certified is distinct from live_digest or certified is distinct from erasure_sha or ready is distinct from true or bound is distinct from certified
