    select 'FUNCTION_AUTHORITY_DRIFT', 'private.retention_ai_source_ready() or the voice surface is executable by a client role'
    where has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE') or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE')
      or has_function_privilege('anon','private.agreement_voice_surface_v1()','EXECUTE') or has_function_privilege('authenticated','private.agreement_voice_surface_v1()','EXECUTE')
      or has_function_privilege('service_role','private.agreement_voice_surface_v1()','EXECUTE')
    union all
    select 'CLOSURE_IN_FLIGHT', 'a closure execution is EXECUTING'
    where exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
